import React from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, BookOpen } from 'lucide-react';

export default function DocLayout({ title, subtitle, children }) {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen w-full bg-[#140c07] text-stone-200 flex flex-col items-center p-4 sm:p-8 select-text">
      {/* Top Header */}
      <div className="w-full max-w-3xl flex items-center justify-between pb-4 border-b border-stone-850">
        <button
          onClick={() => navigate('/')}
          className="flex items-center gap-2 text-xs font-bold text-stone-400 hover:text-amber-400 bg-stone-900/80 hover:bg-stone-850 px-3 py-1.5 rounded-xl border border-stone-800 transition active:scale-95"
        >
          <ArrowLeft size={14} />
          <span>Back to Workspace</span>
        </button>

        <div className="flex items-center gap-1.5 text-xs font-black text-amber-400">
          <BookOpen size={14} />
          <span>booktodotask Docs</span>
        </div>
      </div>

      {/* Main Document Content Sheet */}
      <main className="w-full max-w-3xl mt-6 bg-[#1a120c] border border-amber-950/70 rounded-2xl p-6 sm:p-10 shadow-2xl">
        <header className="border-b border-stone-800/80 pb-4 mb-6">
          <h1 className="text-xl sm:text-2xl font-black text-stone-100 tracking-tight font-sans">
            {title}
          </h1>
          {subtitle && (
            <p className="text-xs text-amber-400/90 font-medium mt-1">
              {subtitle}
            </p>
          )}
        </header>

        <article className="prose prose-invert prose-stone max-w-none text-xs sm:text-sm leading-relaxed text-stone-300 space-y-5">
          {children}
        </article>
      </main>

      <footer className="mt-8 text-center text-[11px] text-stone-500 font-mono">
        © 2026 booktodotask. Built with care for focused minds.
      </footer>
    </div>
  );
}
